		// statement, so the stored row can still be read inside this transaction.
		existing, findErr := findBatch(ctx, tx, "idempotency_key = ?", batch.IdempotencyKey)
		if findErr != nil {
			return Batch{}, false, fmt.Errorf("insert batch: %w", err)
		}
