func (s *Store) Coverage(ctx context.Context, datasetID string) ([]Interval, error) {
	rows, err := s.db.QueryContext(ctx, `
SELECT start_unix_ns, end_unix_ns
FROM dataset_coverage
WHERE dataset_id = ?
ORDER BY start_unix_ns ASC`, datasetID)
