INSERT INTO dataset_coverage (dataset_id, start_unix_ns, end_unix_ns)
VALUES (?, ?, ?)`,
		datasetID, mergedStart, mergedEnd); err != nil {
		return fmt.Errorf("store merged coverage: %w", err)
	}
	return nil
}

